/**
 * Webhook event derivation for the GitHub channel.
 *
 * `agent-sdk github forward` reads the set of webhook events a channel is
 * wired to dispatch (published as `meta.githubWebhookEvents`) so it can build
 * `gh webhook forward --events=…` without the operator hand-listing them.
 */
/** {@link ChannelMeta.kind} value used by {@link githubChannel}. */
export const GITHUB_CHANNEL_KIND = "github";
/**
 * Events the channel always parses through its built-in defaults: the
 * `pull_request` gate and the `@mention` comment gates exist even when no
 * hook is declared.
 */
const BASE_WEBHOOK_EVENTS = [
    "pull_request",
    "issue_comment",
    "pull_request_review_comment",
];
/** Typed opt-in hooks and the webhook event each subscribes to. */
const OPT_IN_HOOK_EVENTS = [
    { option: "onIssue", event: "issues" },
    { option: "onCheckSuite", event: "check_suite" },
    { option: "onCheckRun", event: "check_run" },
    { option: "onWorkflowRun", event: "workflow_run" },
    { option: "onStatus", event: "status" },
];
/**
 * Common events that only reach the `onEvent` catch-all (no typed hook). When
 * `onEvent` is declared we forward these too so review activity is delivered.
 */
const CATCH_ALL_EVENTS = ["pull_request_review", "pull_request_review_thread"];
/**
 * Derive the webhook events a {@link githubChannel} dispatches on from its
 * declared hooks. When {@link GitHubChannelOptions.webhookEvents} is set it is
 * authoritative and returned verbatim (deduped, order preserved) — use it to
 * pin an exact list (e.g. to add events only handled via `onEvent`).
 */
export function deriveGitHubWebhookEvents(options) {
    if (options.webhookEvents !== undefined) {
        return dedupe(options.webhookEvents);
    }
    const events = [...BASE_WEBHOOK_EVENTS];
    for (const { option, event } of OPT_IN_HOOK_EVENTS) {
        if (options[option] !== undefined) {
            events.push(event);
        }
    }
    if (options.onEvent !== undefined) {
        events.push(...CATCH_ALL_EVENTS);
    }
    return dedupe(events);
}
function dedupe(events) {
    return [...new Set(events.map((event) => event.trim()).filter(Boolean))];
}
